from __future__ import annotations
from typing import Sequence

def locate_transition(values: Sequence[int], block_width: int) -> tuple[int, tuple[int, int] | None]:
    if not values or block_width <= 0:
        raise ValueError("nonempty values and a positive block width are required")
    if any(values[i + 1] >= values[i] for i in range(len(values) - 1)):
        raise ValueError("strict sampled descent is required")
    for k, value in enumerate(values):
        if value <= 0:
            return k, None if k == 0 else ((k - 1) * block_width, k * block_width)
    raise ValueError("the sampled sequence has no nonpositive endpoint")

if __name__ == "__main__":
    values = [7, 5, 2, 0, -3]
    print(locate_transition(values, 4))

from __future__ import annotations
from typing import Sequence

def decay_certificate(values: Sequence[int]) -> list[tuple[int, int, int, bool]]:
    if not values:
        raise ValueError("at least one sample is required")
    if any(values[i + 1] >= values[i] for i in range(len(values) - 1)):
        raise ValueError("strict integer descent is required")
    return [(k, value, values[0] - k, value <= values[0] - k) for k, value in enumerate(values)]

if __name__ == "__main__":
    for row in decay_certificate([5, 4, 3, 2, 1, 0]):
        print(row)

