from __future__ import annotations
from typing import Callable

def least_nonpositive_sample(value_at_block: Callable[[int], int], final_block: int) -> int:
    if final_block < 0 or value_at_block(final_block) > 0:
        raise ValueError("a nonpositive final sample is required")
    low, high = 0, final_block
    while low < high:
        middle = (low + high) // 2
        if value_at_block(middle) <= 0:
            high = middle
        else:
            low = middle + 1
    return low

if __name__ == "__main__":
    values = [9, 6, 4, 1, -2, -7]
    print(least_nonpositive_sample(values.__getitem__, len(values) - 1))

